sub('src/server/repositories/issue-repository.ts', '/** Cascade behind `ProjectService.archiveProject`', '''/** Every live issue of a project, in issue-number order — never a page. */
export async function listLiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number, issues.createdAt, issues.id)
    .all();

  const labelsBy = new Map<string, LabelId[]>();
  for (let at = 0; at < rows.length; at += 500) {
    const ids = rows.slice(at, at + 500).map((row) => row.id);
    const links = getDb()
      .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.issueId, ids),
        ),
      )
      .all();
    for (const link of links) {
      const bucket = labelsBy.get(link.issueId) ?? [];
      bucket.push(link.labelId as LabelId);
      labelsBy.set(link.issueId, bucket);
    }
  }

  return rows.map((row) => toIssue(row, labelsBy.get(row.id) ?? []));
}

/**
 * Copies `sources` into `toProjectId` as fresh issues for `ProjectService.cloneProject`
 * (ADR 0012): numbered from 1 in the given order, in `status`, unassigned,
 * unlinked, with no start or completion time, authored by `authorId`. Only
 * title, description, priority, estimate, due date and labels come along.
 * One transaction: either every copy is written or none is.
 */
export async function insertClonedIssues(
  orgId: OrgId,
  toProjectId: ProjectId,
  sources: readonly Issue[],
  authorId: UserId,
  status: IssueStatus,
): Promise<readonly Issue[]> {
  if (sources.length === 0) return [];
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const copies: Issue[] = [];
    let number = 0;
    for (const source of sources) {
      number += 1;
      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId: toProjectId,
          number,
          title: source.title,
          description: source.description,
          status,
          priority: source.priority,
          authorId,
          assigneeId: null,
          parentId: null,
          estimate: source.estimate,
          dueAt: source.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (source.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            source.labelIds.map((labelId) => ({
              orgId,
              issueId: row.id,
              labelId,
            })),
          )
          .run();
      }
      copies.push(toIssue(row, source.labelIds));
    }
    return copies;
  });
}

/** Cascade behind `ProjectService.archiveProject`''')

