sub(p, 'import * as projectRepo from "@/server/repositories/project-repository";', '''import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { issueStatusSchema } from "@/schemas/issue";
import { record } from "./activity-service";
import { indexIssue, indexProject } from "./search-service";''')
sub(p, '  ArchiveProjectInput,\n', '  ArchiveProjectInput,\n  CloneProjectInput,\n')
sub(p, '/** Restore does not un-archive the issues', '''/**
 * Clones a project, optionally with its live issues (ADR 0012). Gated like a
 * creation and checked as a whole before anything is written; the copies are
 * a fresh start (default status, unassigned, renumbered from 1). Publishes
 * only `project.cloned`, so the search index, the usage meters and the audit
 * log are brought up to date here rather than by `*.created` subscribers.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await issueRepo.listLiveIssuesForProject(input.orgId, source.id)
    : [];
  if (
    sourceIssues.length > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)
  ) {
    throw new Error(
      `Plan ${org.plan} does not allow ${sourceIssues.length} issues in one project; nothing was cloned`,
    );
  }

  const parsedStatus = issueStatusSchema.safeParse(
    org.settings.defaultIssueStatus,
  );
  const status = parsedStatus.success ? parsedStatus.data : "backlog";

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  let copies: Awaited<ReturnType<typeof issueRepo.insertClonedIssues>>;
  try {
    copies = await issueRepo.insertClonedIssues(
      input.orgId,
      project.id,
      sourceIssues,
      actor.userId,
      status,
    );
  } catch (error) {
    await projectRepo.deleteProjectRow(input.orgId, project.id);
    throw error;
  }

  await indexProject(input.orgId, project);
  for (const copy of copies) await indexIssue(input.orgId, copy);

  await usageRepo.incrementUsage(input.orgId, {
    projectsUsed: 1,
    issuesUsed: copies.length,
  });

  await record(input.orgId, "project.cloned", {
    actorId: actor.userId,
    subjectKind: "project",
    subjectId: project.id,
    projectId: project.id,
    summary: `Cloned project ${source.name} as ${project.name} with ${copies.length} issues`,
    metadata: { sourceProjectId: source.id, issuesCopied: copies.length },
  });

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: copies.length,
  });

  return project;
}

/** Restore does not un-archive the issues''')
