cat > tests/services/zz-clone-smoke.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("clones", async () => {
  const t = await createTenant("clonesmoke", "growth");
  const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "A" }));
  await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "B" }));
  await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "C" }));
  await issueRepo.archiveIssue(t.org.id, a.id);
  const p = await projectService.cloneProject(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "Copy", slug: "platform", key: "CPY", includeIssues: true });
  expect(p.slug).toBe("platform-2");
  const copies = await issueRepo.listLiveIssuesForProject(t.org.id, p.id);
  expect(copies.map((i) => [i.number, i.title, i.status, i.assigneeId])).toEqual([[1, "B", "backlog", null], [2, "C", "backlog", null]]);
  console.log(await usageRepo.getUsage(t.org.id), await searchRepo.countIndexed(t.org.id));
  console.log((await activityRepo.listActivity({ orgId: t.org.id, limit: 10, cursor: null })).items);
});
EOF
npx vitest run 2>&1 | tail -40; rm tests/services/zz-clone-smoke.test.ts

